window.RSTS_COURSE_DATA = {"schemaVersion":"0.1","courseId":"gov.oceanview.ada-title-ii-2026","title":"ADA Title II \u0026 Accessible Digital Services","organization":"City of Ocean View \u2014 Department of Human Resources","version":"1.0.0","defaultLanguage":"en-US","scormStandard":"1.2","masteryScore":80,"lockForwardScrubbing":true,"subSlideCommitIntervalSeconds":10,"slides":[{"id":"01-foundations","index":0,"type":"narrated-html","title":"Why Accessible, Bandwidth-Light Courseware Matters","lang":"en-US","bodyHtml":"\u003Ch3\u003EDelivering Public Services Every Resident and Employee Can Reach\u003C/h3\u003E\r\n\u003Cp\u003EUnder \u003Cstrong\u003EADA Title II Subpart H\u003C/strong\u003E, municipal websites, recreation portals, transit schedules, and mandatory employee training modules must meet \u003Cstrong\u003EWCAG 2.1 / 2.2 Level AA\u003C/strong\u003E accessibility standards\u2014whether accessed at City Hall or from a low-bandwidth Parks and Recreation field counter.\u003C/p\u003E\r\n\u003Cul\u003E\r\n  \u003Cli\u003E\u003Cstrong\u003ESemantic HTML5 First:\u003C/strong\u003E Real headings, lists, and high-contrast text resize cleanly up to \u003Ccode\u003E400%\u003C/code\u003E zoom and read naturally with NVDA, JAWS, Narrator, and VoiceOver.\u003C/li\u003E\r\n  \u003Cli\u003E\u003Cstrong\u003EZero 400 MB Video Bloat:\u003C/strong\u003E Pairing native HTML5 layouts with compressed Opus/AAC voiceover audio reduces slide bandwidth by more than \u003Ccode\u003E98%\u003C/code\u003E.\u003C/li\u003E\r\n\u003C/ul\u003E","timedCues":[{"id":"cue-1","startSeconds":5,"label":"Branch-Office Bandwidth Resilience","html":"\u003Cp\u003EWhen thousands of municipal employees complete training before a compliance deadline, lightweight HTML5 \u002B \u003Ccode\u003E48 kbps\u003C/code\u003E Opus audio prevents \u003Ccode\u003EHTTP 206\u003C/code\u003E WAN congestion at recreation centers, fire stations, and transit depots.\u003C/p\u003E"},{"id":"cue-2","startSeconds":11,"label":"Atomic Sub-Slide Checkpointing","html":"\u003Cp\u003EEvery \u003Ccode\u003E10 seconds\u003C/code\u003E and on every slide boundary, progress is recorded to a local Write-Ahead Queue before calling \u003Ccode\u003ELMSCommit()\u003C/code\u003E, ensuring VPN drops never erase completed watch time.\u003C/p\u003E"}],"media":{"sources":[{"src":"media/01-narration.opus","mimeType":"audio/ogg; codecs=opus"},{"src":"media/01-narration.m4a","mimeType":"audio/mp4"}],"durationSeconds":18,"captionsVttPath":"captions/01-narration.en-US.vtt","cues":[{"id":"vtt-1","startSeconds":0,"endSeconds":4.9,"text":"Welcome to the City of Ocean View ADA Title II accessibility briefing."},{"id":"vtt-2","startSeconds":5,"endSeconds":10.9,"text":"Semantic HTML5 slides and compact Opus audio keep branch networks responsive."},{"id":"vtt-3","startSeconds":11,"endSeconds":18,"text":"Atomic ten-second checkpoints protect your progress even if a proxy drops."}]},"completionRule":"media-ended"},{"id":"02-knowledge-check","index":1,"type":"knowledge-check","title":"Scenario Check: Branch-Office Networks \u0026 Screen Readers","lang":"en-US","bodyHtml":"\u003Ch3\u003EApply What You Learned: Accessibility \u0026amp; Network Resilience\u003C/h3\u003E\r\n\u003Cp\u003EReview the real-world municipal deployment scenario below and select the compliant engineering approach.\u003C/p\u003E","timedCues":[],"quiz":[{"id":"q_ada_bandwidth","prompt":"A Parks \u0026 Recreation department needs to deliver a 15-minute ADA Title II training module to 2,500 staff across congested branch-office links. Which format meets WCAG 2.2 AA and prevents HTTP 206 stalls?","choices":[{"id":"opt_mp4","text":"Export static bullet slides into a single 420 MB progressive MP4 video without a transcript."},{"id":"opt_html5","text":"Author semantic HTML5 slides with compressed Opus/AAC voiceover, synchronized WebVTT captions, and atomic cue checkpoints."},{"id":"opt_pdf","text":"Upload an untagged scanned image PDF and ask employees to email HR when finished."}],"correctChoiceId":"opt_html5","explanationPass":"Correct! Semantic HTML5 \u002B lightweight audio \u002B synchronized WebVTT captions satisfies WCAG 2.2 Level AA while eliminating 400 MB video stalls.","explanationRetry":"Not quite\u2014monolithic progressive MP4s and untagged scanned PDFs create severe bandwidth stalls and screen-reader barriers. Try again!"}],"completionRule":"quiz-passed"},{"id":"03-attestation","index":2,"type":"attestation","title":"Municipal ADA Title II Employee Attestation","lang":"en-US","bodyHtml":"\u003Ch3\u003EComplete Your Annual Digital Accessibility Attestation\u003C/h3\u003E\r\n\u003Cp\u003EThank you for completing the scenario review. Submitting your attestation below records your \u003Ccode\u003E100%\u003C/code\u003E mastery score, session duration, and completion status directly to the Learning Management System (or holds it safely in your local Write-Ahead Queue if your network is temporarily offline).\u003C/p\u003E","timedCues":[],"attestation":{"statementText":"As a City of Ocean View team member (fictitious sample organization), I understand that public-facing and internal digital content\u2014including documents, captions, forms, and training\u2014must conform to WCAG 2.2 Level AA accessibility standards.","checkboxLabel":"I confirm that I have completed this module and will verify captions, alt text, keyboard navigation, and color contrast before publishing digital materials.","submitButtonLabel":"Sign Attestation \u0026 Complete Course"},"completionRule":"attestation-signed"}]};
